  ('settings', '{"brand":{"display":"Mynsera","formerly":"Dream Craft","tagline":"Invitations, florals & keepsakes, made by hand in Shillong","description":"Mynsera (formerly Dream Craft) handcrafts custom wedding invitations, bouquets, boutonnieres, ring holders, cake toppers and personalised gifts in Shillong, Meghalaya. Get an approximate quote in minutes.","showFormerly":true,"wordmarkAccentLetter":""},"contact":{"location":"Shillong, Meghalaya","shipping":"Shipping across India & abroad","instagramHandle":"@dreamcraft","instagramUrl":"https://www.instagram.com/dreamcraft","whatsappNumber":"","whatsappLink":"https://wa.me/message/4C2ID7G54JAIJ1","email":""},"ticker":["Dream Craft is now Mynsera","Now booking 2026–27 weddings","Handmade in Shillong","Shipping across India & abroad"],"footer":{"startTitle":"Start here","startText":"Tell us what you''re planning. Upload your inspiration and get an approximate price in about two minutes.","madeIn":"Handmade in Meghalaya"}}'::jsonb, '{"brand":{"display":"Mynsera","formerly":"Dream Craft","tagline":"Invitations, florals & keepsakes, made by hand in Shillong","description":"Mynsera (formerly Dream Craft) handcrafts custom wedding invitations, bouquets, boutonnieres, ring holders, cake toppers and personalised gifts in Shillong, Meghalaya. Get an approximate quote in minutes.","showFormerly":true,"wordmarkAccentLetter":""},"contact":{"location":"Shillong, Meghalaya","shipping":"Shipping across India & abroad","instagramHandle":"@dreamcraft","instagramUrl":"https://www.instagram.com/dreamcraft","whatsappNumber":"","whatsappLink":"https://wa.me/message/4C2ID7G54JAIJ1","email":""},"ticker":["Dream Craft is now Mynsera","Now booking 2026–27 weddings","Handmade in Shillong","Shipping across India & abroad"],"footer":{"startTitle":"Start here","startText":"Tell us what you''re planning. Upload your inspiration and get an approximate price in about two minutes.","madeIn":"Handmade in Meghalaya"}}'::jsonb, now()),
  ('home', '{"sections":["make","process","gallery","packages","story","cta"],"hero":{"eyebrow":"Formerly Dream Craft · Shillong","line1":"Invitations,","line2":"florals & keepsakes","line3":"made by hand.","lede":"Custom wedding stationery, bouquets and personalised pieces. Share your idea and get an approximate quote in about two minutes.","primaryButton":"Get a quote","secondaryButton":"See our work","image":"asset:bouquet-terracotta.jpg","imageAlt":"Terracotta rose and pampas bridal bouquet","cards":[{"image":"asset:wedding-card-nr.jpg","title":"Invitations","text":"foiled & hand-finished"},{"image":"asset:ring-holder-round.jpg","title":"Ring holders","text":"engraved to order"}],"trust":[{"value":"2,500+","label":"follow the studio"},{"value":"10","label":"things we make"},{"value":"Worldwide","label":"shipping"}]},"make":{"eyebrow":"What we make","title":"Ten ways to make it","titleAccent":"yours","lede":"Everything is made to order. Pick one to start a quote with it already chosen."},"process":{"eyebrow":"How it works","title":"From idea to","titleAccent":"doorstep","lede":"No back-and-forth to get started. Everything we need arrives in one enquiry, so we can reply with a real quote.","button":"Start my quote","steps":[{"title":"Share your inspiration","text":"Upload screenshots, Pinterest saves or photos of our work you love."},{"title":"Choose the details","text":"Size, colour, paper, finishing, quantity and budget, all tap-to-select."},{"title":"See an approximate price","text":"An estimate appears as you choose. No waiting to find out if it fits."},{"title":"We review & quote","text":"We study your enquiry and send a final written quotation."},{"title":"Confirm your order","text":"Approve the quote and design, then we reserve your production slot."},{"title":"Made by hand, delivered","text":"Crafted in our Shillong studio and dispatched by courier."}]},"gallery":{"title":"From the","titleAccent":"studio","link":"All work","itemHint":"Quote something like 